class Solution:
    def findNthDigit(self, n: int) -> int:
        def count_through(value):
            total, start, width = 0, 1, 1
            while start <= value:
                total += (min(value, start * 10 - 1) - start + 1) * width
                start *= 10
                width += 1
            return total
        low, high = 1, n
        while low < high:
            middle = (low + high) // 2
            if count_through(middle) >= n:
                high = middle
            else:
                low = middle + 1
        offset = n - count_through(low - 1) - 1
        return int(str(low)[offset])
